#include <iostream>

class RegistroBase {
public:
    explicit RegistroBase(int numero) : numero_{numero} {}
    int leer() const { return numero_; }
protected:
    void guardar(int numero) { numero_ = numero; }
private:
    int numero_;
};
int consultar_registro(const RegistroBase& registro) {
    return registro.leer();
}
class Intermedia : protected RegistroBase {
public:
    explicit Intermedia(int numero) : RegistroBase{numero} {}
    int consulta() const { return RegistroBase::leer(); }
};
class Posterior : public Intermedia {
public:
    explicit Posterior(int numero) : Intermedia{numero} {}
    void cambiar(int numero) { guardar(numero); }
    int por_referencia() const { return consultar_registro(*this); }
    int por_puntero() const {
        const RegistroBase* vista = this;
        return vista->leer();
    }
};
int main() {
    Posterior dato{4};
    std::cout << dato.consulta() << '|';
    dato.cambiar(9);
    std::cout << dato.consulta() << ':' << dato.por_referencia()
              << ':' << dato.por_puntero();
    return 0;
}

